const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function icons(){$$('[data-icon]').forEach(e=>e.style.setProperty('--icon',`url("${iconURLs[e.dataset.icon]}")`));}
function notify(s){$('#toast').textContent=s;$('#toast').hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').hidden=true,3000);}
$('#theme').onclick=()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';};
$$('[data-section]').forEach(b=>b.onclick=()=>{$$('[data-section]').forEach(x=>x.classList.toggle('active',x===b));$$('[data-page]').forEach(x=>x.hidden=x.dataset.page!==b.dataset.section);$('#saved').textContent='设置仅影响之后的生成任务';});
$$('[data-feedback]').forEach(b=>b.onclick=()=>notify(b.dataset.feedback));
if($('#save-panel')){$('#save-panel').onclick=()=>{$('#saved').textContent='本页设置已应用到原型';notify('已应用示例配置，未写入本地设置。');};$('#provider2').onchange=()=>{$('#model2').innerHTML=($('#provider2').value==='DeepSeek'?['deepseek-chat','deepseek-reasoner']:$('#provider2').value==='百炼'?['qwen-plus','qwen-max']:['custom-model']).map(m=>`<option>${m}</option>`).join('');};$('#add-rule').onclick=()=>{$('.tag-table tbody').insertAdjacentHTML('beforeend','<tr><td contenteditable="true">新标签</td><td contenteditable="true">替换文本</td><td contenteditable="true">(.*?)</td></tr>');};}
const entries=[['download','14:32:01','剧情资源已准备好','命中本地缓存 · 孤星 / 4 章','未下载重复资源。'],['script','14:32:02','原始剧本已保存','Markdown / HTML','按章节顺序输出对白与场景。'],['novel','14:32:06','CW-1 行动前 · 已完成','查看本轮输入与输出','输入：本章剧情文本。\n输出：连贯的小说叙事。\n正式应用中打开对应的模型复盘记录。'],['novel','14:32:18','CW-1 行动后 · 已完成','复用了已有小说缓存','相同剧本与模型的结果直接复用。'],['novel','14:32:32','CW-2 行动前 · 已完成','小说已保存','成功结果已写入输出目录。'],['novel','14:33:32','CW-2 行动后 · 请求超时','失败 · 可重试此章','模型服务未在等待时间内返回。\n已完成章节仍然保留。重新生成会复用成功缓存。',true],['export','14:33:34','已导出成功章节的 EPUB','3 / 4 章 · 部分完成','EPUB 仅包含成功生成的章节，不代表全部成功。']];let stage='all';
function render(){if(!$('#log-entries'))return;const rows=entries.filter(e=>(stage==='all'||e[0]===stage)&&(!$('#errors-only').checked||e[5]));$('#log-entries').innerHTML=rows.map(e=>`<details class="log-entry ${e[5]?'error':''}"><summary><time>${e[1]}</time><i data-icon="${e[5]?'alert-circle-outline':'check'}"></i><span class="log-text">${e[2]}<small>${e[3]}</small></span><i data-icon="chevron-down"></i></summary><p>${e[4]}</p></details>`).join('');$('#log-count').textContent=`显示 ${rows.length} / ${entries.length} 条记录`;icons();}
if($('#log-entries')){$$('[data-stage]').forEach(b=>b.onclick=()=>{stage=b.dataset.stage;$$('[data-stage]').forEach(x=>x.classList.toggle('active',x===b));render();});$('#errors-only').onchange=render;$('#locate').onclick=()=>{$('[data-stage="novel"]').click();$('#errors-only').checked=true;render();$('.log-entry').open=true;};$('#follow').onchange=()=>notify($('#follow').checked?'新记录到达时自动跟随':'已暂停跟随，可查看前面的记录');$('#export-log').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([entries.map(e=>`${e[1]} ${e[2]}\n${e[4]}`).join('\n\n')],{type:'text/plain;charset=utf-8'}));a.download='ArkPlot-示例日志.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};render();}icons();
